914: /// One judged window (`Get-QuotaWindowStates`).
915: #[derive(Debug, Clone)]
916: pub struct WindowState {
917:     /// `primary` | `secondary`.
918:     pub key: &'static str,
919:     pub name: String,
920:     pub short: String,
921:     pub used: f64,
922:     pub resets_at: Option<DateTime<FixedOffset>>,
923:     /// The reset lies in the past.
924:     pub reset: bool,
925:     /// At [`QUOTA_BLOCK_PERCENT`] or more with its reset ahead.
926:     pub blocks: bool,
927:     /// At [`QUOTA_WARN_PERCENT`] or more, not reset.
928:     pub low: bool,
929: }
930: 
931: /// `Get-QuotaWindowStates`: the windows of a recorded quota (`{primary, secondary}`), judged at
932: /// `now`.
933: pub fn window_states(quota: &Value, now: DateTime<Utc>) -> Vec<WindowState> {
934:     let mut out = Vec::new();
935:     if !quota.is_object() {
936:         return out;
937:     }
938:     for key in ["primary", "secondary"] {
939:         let w = &quota[key];
940:         if !w.is_object() {
941:             continue;
942:         }
943:         let used = match finite_percent(&w["used_percent"]) {
944:             Some(f) => f,
945:             None => continue,
946:         };
947:         let minutes = w["window_minutes"].as_i64().or_else(|| {
948:             w["window_minutes"]
949:                 .as_str()
950:                 .and_then(|s| s.trim().parse().ok())
951:         });
952:         let resets_at = when_offset(&w["resets_at"]);
953:         let reset = resets_at
954:             .map(|r| r.with_timezone(&Utc) <= now)
955:             .unwrap_or(false);
956:         out.push(WindowState {
957:             key,
958:             name: window_name(minutes, false),
959:             short: window_name(minutes, true),
960:             used,
961:             resets_at,
962:             reset,
963:             blocks: !reset && resets_at.is_some() && used >= QUOTA_BLOCK_PERCENT,
964:             low: !reset && used >= QUOTA_WARN_PERCENT,
965:         });
966:     }
967:     out
968: }
