970: /// `Format-QuotaWindows`: `5h 96% until 18:32; wk 15% until Oct 20` (local times), a window whose
971: /// reset lies in the past `5h reset (last 96% until 18:32)`; `""` when the quota names no window.
972: pub fn format_windows(quota: &Value, now: DateTime<Utc>) -> String {
973:     let mut parts: Vec<String> = Vec::new();
974:     for s in window_states(quota, now) {
975:         let pct = format!("{}%", format_percent(s.used));
976:         match s.resets_at {
977:             None => parts.push(format!("{} {pct}", s.short)),
978:             Some(r) if s.reset => parts.push(format!(
979:                 "{} reset (last {pct} until {})",
980:                 s.short,
981:                 format_reset(r, now)
982:             )),
983:             Some(r) => parts.push(format!("{} {pct} until {}", s.short, format_reset(r, now))),
984:         }
985:     }
986:     parts.join("; ")
987: }
