989: /// `Format-QuotaLowWarning`: `low quota: 5-hour window 84 % until 18:32` (the fullest window at
990: /// [`QUOTA_WARN_PERCENT`] or more), `""` otherwise.
991: pub fn format_low_warning(quota: &Value, now: DateTime<Utc>) -> String {
992:     let mut low: Vec<WindowState> = window_states(quota, now)
993:         .into_iter()
994:         .filter(|s| s.low)
995:         .collect();
996:     if low.is_empty() {
997:         return String::new();
998:     }
999:     low.sort_by(|a, b| {
1000:         b.used
1001:             .partial_cmp(&a.used)
1002:             .unwrap_or(std::cmp::Ordering::Equal)
1003:     });
1004:     let s = &low[0];
1005:     let until = s
1006:         .resets_at
1007:         .map(|r| format!(" until {}", format_reset(r, now)))
1008:         .unwrap_or_default();
1009:     format!("low quota: {} {} %{until}", s.name, format_percent(s.used))
1010: }
