1012: /// The blocking window with the latest reset (`New-QuotaWindowRecord`'s choice), `None` when none
1013: /// blocks.
1014: pub fn blocking_window(quota: &Value, now: DateTime<Utc>) -> Option<WindowState> {
1015:     let mut b: Vec<WindowState> = window_states(quota, now)
1016:         .into_iter()
1017:         .filter(|s| s.blocks)
1018:         .collect();
1019:     b.sort_by_key(|x| std::cmp::Reverse(x.resets_at));
1020:     b.into_iter().next()
1021: }
